<template>
  <section class="workspace-panel">
    <div class="section-heading"><div><h2>Clinical Stage</h2><p>查看量表来源、canonical 预览与纵向可比性。预览不会保存。</p></div></div>
    <div class="toolbar"><label>评估记录<select v-model="assessmentId" @change="loadDetail"><option value="">请选择</option><option v-for="a in assessments" :key="a.id" :value="a.id">{{ a.assessment_type }} · {{ formatDateTime(a.assessed_at) }}</option></select></label><label>对比记录<select v-model="compareId"><option value="">请选择</option><option v-for="a in assessments.filter(x=>x.id!==assessmentId)" :key="a.id" :value="a.id">{{ formatDateTime(a.assessed_at) }}</option></select></label><button class="secondary-button" :disabled="!assessmentId||!compareId" @click="compare">比较</button></div>
    <AsyncState :loading="loading" :error="error" :empty="!assessmentId" empty-title="请选择评估记录" empty-text="选择一条现有评估后查看 Clinical Stage。" @retry="loadDetail">
      <div v-if="detail" class="panel-grid two"><article class="surface-card"><h3>临床来源</h3><JsonDetails :value="detail.source" /></article><article class="surface-card"><h3>Canonical 结果</h3><StatusBadge :status="String(detail.canonical_preview?.status||'review_required')"/><JsonDetails :value="detail.canonical_preview" /></article></div>
      <div class="action-row"><button class="secondary-button" :disabled="!assessmentId" @click="preview">预览 canonical（不保存）</button><button class="secondary-button" :disabled="!assessmentId" @click="showEdit=!showEdit">更新来源数据</button></div>
      <form v-if="showEdit" class="form-panel compact-form" @submit.prevent="updateSource"><h3>Clinical source metadata</h3><div class="form-grid"><label>量表名称<input v-model="sourceForm.instrument_name" /></label><label>版本<input v-model="sourceForm.instrument_version" /></label><label>语言区域<input v-model="sourceForm.language_locale" /></label><label>单位<input v-model="sourceForm.score_unit" /></label></div><label>修订原因<textarea v-model="sourceForm.revision_reason" required /></label><button class="primary-button" :disabled="saving">{{ saving?'保存中…':'保存来源数据' }}</button></form>
      <article v-if="previewData" class="surface-card"><h3>Canonical 预览（未保存）</h3><JsonDetails :value="previewData" /></article>
      <article v-if="comparison" class="surface-card"><h3>纵向比较</h3><StatusBadge :status="String(comparison.status||'review_required')"/><JsonDetails :value="comparison" /></article>
    </AsyncState>
  </section>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { therapistApi } from '@/api/therapist'; import { clinicalStageApi } from '@/api/clinicalStage'; import AsyncState from '@/components/common/AsyncState.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { formatDateTime } from '@/utils/date'; import type { AssessmentSession } from '@/types/api'; import type { ClinicalStageDetail,ComparabilityResult,JsonObject } from '@/types/professional'
const props=defineProps<{patientId:string}>(); const assessments=ref<AssessmentSession[]>([]),assessmentId=ref(''),compareId=ref(''),detail=ref<ClinicalStageDetail|null>(null),previewData=ref<JsonObject|null>(null),comparison=ref<ComparabilityResult|null>(null),loading=ref(true),saving=ref(false),error=ref(''),showEdit=ref(false); const sourceForm=ref({instrument_name:'',instrument_version:'',language_locale:'zh-CN',score_unit:'',revision_reason:''})
async function initial(){loading.value=true;error.value='';try{assessments.value=await therapistApi.assessmentHistory(props.patientId);if(assessments.value[0]){assessmentId.value=assessments.value[0].id;await loadDetail()}}catch(e){error.value=message(e)}finally{loading.value=false}}
async function loadDetail(){if(!assessmentId.value)return;loading.value=true;error.value='';try{detail.value=await clinicalStageApi.detail(props.patientId,assessmentId.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function preview(){try{previewData.value=await clinicalStageApi.preview(props.patientId,assessmentId.value)}catch(e){error.value=message(e)}} async function compare(){try{comparison.value=await clinicalStageApi.compare(props.patientId,assessmentId.value,compareId.value)}catch(e){error.value=message(e)}}
async function updateSource(){saving.value=true;error.value='';try{await clinicalStageApi.updateSource(props.patientId,assessmentId.value,sourceForm.value);showEdit.value=false;await loadDetail()}catch(e){const m=message(e);error.value=m.includes('final')||m.includes('确认')?'该评估已确认，请通过 Review 流程修改。':m}finally{saving.value=false}}
function message(e:unknown){return e instanceof Error?e.message:'操作失败'} onMounted(initial)
</script>
